definition.script:
pipeline {
  agent any

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '10', artifactNumToKeepStr: '3'))
    timeout(time: 150, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  environment {
    NEXUS_REGISTRY = 'localhost:5001'
    SLUG = 'johndoe6345789/next_extra_primary'
    NEXUS_BASE_URL = 'http://nexus:8081'
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/businessplanner.git'
      }
    }

    stage('Begin base lock') {
      steps {
        // Cross-agent sentinel: docker-housekeeping skips its prune while this
        // Docker volume exists, so a concurrent prune cannot fight the build.
        sh 'docker volume create mb-base-running >/dev/null 2>&1 || true'
        sh 'docker builder prune -f --filter until=48h || true'
      }
    }

    // Disk-safe SERIAL pipeline. Order matters: nextra-base-apt is built first
    // and kept resident because nextra-base-conan builds FROM it (local). node
    // has no local dependents, so it is pruned immediately. base-apt is dropped
    // at the very end. Peak disk ~= base-apt + one dependent.
    stage('Build+Push+Prune base images') {
      options { timeout(time: 140, unit: 'MINUTES') }
      steps {
        withCredentials([usernamePassword(credentialsId: 'nexus-admin', usernameVariable: 'NEXUS_ADMIN_USER', passwordVariable: 'NEXUS_ADMIN_PASSWORD')]) {
          sh '''
            docker version
            printf '%s' "$NEXUS_ADMIN_PASSWORD" | docker login "$NEXUS_REGISTRY" -u "$NEXUS_ADMIN_USER" --password-stdin
          '''
          script {
            def bases = [
              [name: 'nextra-base-apt',   file: '.local/docker/nextra-base-apt.Dockerfile',   keep: '1', args: ''],
              [name: 'nextra-base-conan', file: '.local/docker/nextra-base-conan.Dockerfile', keep: '0', args: '--build-arg APT_IMAGE=localhost:5001/johndoe6345789/next_extra_primary/nextra-base-apt:latest'],
              [name: 'nextra-base-node',  file: '.local/docker/nextra-base-node.Dockerfile',  keep: '0', args: ''],
            ]
            for (b in bases) {
              stage("base: ${b.name}") {
                catchError(message: "base ${b.name} failed -- dependent apps fall back to the last-good base in Nexus", buildResult: 'UNSTABLE', stageResult: 'FAILURE') {
                  withEnv(["BASE_NAME=${b.name}", "BASE_FILE=${b.file}", "BASE_ARGS=${b.args}", "KEEP_LOCAL=${b.keep}"]) {
                    sh '''
                      set -e
                      docker build -f "$BASE_FILE" $BASE_ARGS \
                        -t "$NEXUS_REGISTRY/$SLUG/$BASE_NAME:latest" .
                    '''
                    sh '''
                      set -e
                      python3 - <<'PY'
import json
import os
import subprocess

registry = os.environ["NEXUS_REGISTRY"]
slug = os.environ["SLUG"]
nexus_url = os.environ["NEXUS_BASE_URL"]
user = os.environ["NEXUS_ADMIN_USER"]
pw = os.environ["NEXUS_ADMIN_PASSWORD"]
name = os.environ["BASE_NAME"]
keep = os.environ.get("KEEP_LOCAL") == "1"
tag = subprocess.check_output(["git", "rev-parse", "--short", "HEAD"], text=True).strip()

local = registry + "/" + slug + "/" + name + ":latest"

def delete_existing(version):
    import base64
    import urllib.parse
    import urllib.request
    q = urllib.parse.urlencode({"repository": "docker-hosted", "name": slug + "/" + name, "version": version})
    auth = base64.b64encode((user + ":" + pw).encode()).decode()
    req = urllib.request.Request(nexus_url + "/service/rest/v1/search?" + q, headers={"Authorization": "Basic " + auth})
    with urllib.request.urlopen(req, timeout=30) as r:
        payload = json.load(r)
    for item in payload.get("items", []):
        if item.get("name") == slug + "/" + name and item.get("version") == version:
            dr = urllib.request.Request(nexus_url + "/service/rest/v1/components/" + item["id"], method="DELETE", headers={"Authorization": "Basic " + auth})
            with urllib.request.urlopen(dr, timeout=30):
                pass
            print("Deleted old Nexus component " + slug + "/" + name + ":" + version)

for version in ("sha-" + tag, "latest"):
    target = registry + "/" + slug + "/" + name + ":" + version
    delete_existing(version)
    subprocess.check_call(["docker", "tag", local, target])
    subprocess.check_call(["docker", "push", target])
    if target != local:
        subprocess.run(["docker", "rmi", "-f", target], check=False)
print("Pushed " + slug + "/" + name + " (sha-" + tag + ", latest)")

if keep:
    print("Kept local " + local + " (local dependents build FROM it)")
else:
    repo = local.split(":")[0]
    listed = subprocess.run(["docker", "images", "--format", "{{.Repository}}:{{.Tag}}"], capture_output=True, text=True).stdout.splitlines()
    for ln in listed:
        if ln.split(":")[0] == repo:
            subprocess.run(["docker", "rmi", "-f", ln], check=False)
    subprocess.run(["docker", "builder", "prune", "-f", "--filter", "until=24h"], check=False)
    print("Pruned local " + repo + " (freed disk before next base)")
PY
                    '''
                  }
                }
              }
            }
            stage('drop base-apt') {
              sh '''
                docker images --format '{{.Repository}}:{{.Tag}}' \
                  | grep '/nextra-base-apt:' \
                  | xargs -r docker rmi -f 2>/dev/null || true
                docker builder prune -f --filter until=24h || true
              '''
            }
          }
        }
      }
    }
  }

  post {
    always {
      sh 'docker volume rm -f mb-base-running >/dev/null 2>&1 || true'
      cleanWs()
    }
  }
}
